import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let l = {l}. Define the overpartition function R_l_star(n) to be the number of overpartitions of n in which non-overlined parts are not allowed to be divisible by l (overlined parts are unrestricted). It is known that the generating function satisfies sum_{n>=0} R_l_star(n) q^n = (prod_{m>=1} (1 - q^{2m})) (prod_{m>=1} (1 - q^{lm})) / (prod_{m>=1} (1 - q^m))^2. Fix an integer tau = {tau_exponent} and work modulo M = 2^{tau}. Let k = {k}, and define the arithmetic progression parameters D = {d_step} and A = {a_base}, where D = 18 * 3^{2k+1} and A = (153 * 3^{2k} - 1) / 4 (both already simplified to integers here). For N = {n_terms}, compute the alternating progression sum S = sum_{j=0}^{N} (-1)^j R_l_star(A + D * j) modulo M. Report S as an integer in [0, M - 1].'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We keep l fixed at 6 to preserve the seed's core structure (3-adic dissection with 2-adic modulus),
# but we significantly increase difficulty by asking for an alternating sum over a long arithmetic progression
# and by working modulo higher powers of 2.
l = 6
# Choose tau so that modulus >= 128; 2^7=128, 2^8=256
tau = rng.choice([7, 8])
# Choose k to control step size; keep it small enough to allow feasible DP while still nontrivial
k = rng.choice([0, 1])
# Compute D and A
D = 18 * (3 ** (2 * k + 1))
A = (153 * (3 ** (2 * k)) - 1) // 4  # guaranteed integer
# Choose N based on k to keep max_n manageable while nontrivial
if k == 0:
    N = rng.randint(20, 35)
else:
    N = rng.randint(5, 6)
# Final sanity check on size
max_n = A + D * N
# Ensure within safe computation limits (rough O(max_n^2))
# Target max_n <= 3500
tries = 0
while max_n > 3500 and tries < 20:
    # reduce N if too big
    if k == 0:
        N = rng.randint(18, 28)
    else:
        N = rng.randint(4, 5)
    max_n = A + D * N
    tries += 1
if max_n > 3500:
    # As a fallback, force smaller parameters deterministically
    k = 0
    D = 18 * (3 ** (2 * k + 1))
    A = (153 * (3 ** (2 * k)) - 1) // 4
    N = 24
    max_n = A + D * N
return {
    'l': l,
    'tau_exponent': tau,
    'k': k,
    'd_step': D,
    'a_base': A,
    'n_terms': N
}

    def verifier(assign):
# Validate presence
for key in ['l', 'tau_exponent', 'k', 'd_step', 'a_base', 'n_terms']:
    if key not in assign:
        return (False, None)  # missing key
l = assign['l']
tau = assign['tau_exponent']
k = assign['k']
D = assign['d_step']
A = assign['a_base']
N = assign['n_terms']
# Domain checks
if not (isinstance(l, int) and isinstance(tau, int) and isinstance(k, int) and isinstance(D, int) and isinstance(A, int) and isinstance(N, int)):
    return (False, None)
if l != 6:
    return (False, None)  # fixed to preserve seed structure
if tau not in (7, 8):
    return (False, None)
if k not in (0, 1):
    return (False, None)
# Check D and A match the specified formulas
if D != 18 * (3 ** (2 * k + 1)):
    return (False, None)
if A != (153 * (3 ** (2 * k)) - 1) // 4:
    return (False, None)
if N < 0:
    return (False, None)
mod = 1 << tau
mask = mod - 1
max_n = A + D * N
if max_n < 0 or max_n > 3500:
    return (False, None)
# Compute R_l^*(n) modulo mod up to max_n via the factorization:
# G(q) = prod_{s>=1} (1 + q^s) * prod_{t>=1, l \nmid t} (1 - q^t)^{-1}
# Truncated to max_n is exact for coefficients up to q^{max_n}
ways = [0] * (max_n + 1)
ways[0] = 1
# Multiply by prod_{s=1..max_n} (1 + q^s)
for s in range(1, max_n + 1):
    step = s
    # reverse loop to avoid overcounting within this factor
    for n in range(max_n, step - 1, -1):
        ways[n] = (ways[n] + ways[n - step]) & mask
# Multiply by prod_{t=1..max_n, l \nmid t} (1 - q^t)^{-1} = sum_{m>=0} q^{m t}, unbounded knapsack forward loop
for t in range(1, max_n + 1):
    if t % l != 0:
        for n in range(t, max_n + 1):
            ways[n] = (ways[n] + ways[n - t]) & mask
# Accumulate alternating sum S = sum_{j=0}^N (-1)^j ways[A + D*j]
S = 0
for j in range(N + 1):
    idx = A + D * j
    if idx < 0 or idx > max_n:
        return (False, None)
    val = ways[idx]
    if (j & 1) == 0:
        S = (S + val) & mask
    else:
        S = (S - val) & mask
answer = S & mask
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

